//! Pure codecs for the Ecliptic Remote Desktop version 3 wire protocol.
//!
//! This crate performs no I/O. It only converts validated protocol values to
//! and from their byte-exact wire representation and incrementally parses the
//! TCP length-prefix framing used by the transport layer.

mod codec;
mod control;
mod error;
mod framing;
mod handshake;
mod input;
mod media;
mod packet;
mod pairing;

pub use control::*;
pub use error::CodecError;
pub use framing::*;
pub use handshake::*;
pub use input::*;
pub use media::*;
pub use packet::*;
pub use pairing::*;

/// A value with a complete version 3 wire encoding.
pub trait WireCodec: Sized {
    /// Encodes this value into its canonical wire representation.
    fn encode(&self) -> Result<Vec<u8>, CodecError>;

    /// Decodes one complete value from `input`.
    fn decode(input: &[u8]) -> Result<Self, CodecError>;
}

use std::ops::{BitOr, BitOrAssign};

use crate::{
    codec::{push_f32, push_u16, Decoder},
    CodecError, WireCodec,
};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum InputEventType {
    MouseMove = 0,
    LeftMouseDown = 1,
    LeftMouseUp = 2,
    RightMouseDown = 3,
    RightMouseUp = 4,
    ScrollWheel = 5,
    KeyDown = 6,
    KeyUp = 7,
    FlagsChanged = 8,
    LeftMouseDragged = 9,
    RightMouseDragged = 10,
}

impl InputEventType {
    pub const ALL: [Self; 11] = [
        Self::MouseMove,
        Self::LeftMouseDown,
        Self::LeftMouseUp,
        Self::RightMouseDown,
        Self::RightMouseUp,
        Self::ScrollWheel,
        Self::KeyDown,
        Self::KeyUp,
        Self::FlagsChanged,
        Self::LeftMouseDragged,
        Self::RightMouseDragged,
    ];
}

impl TryFrom<u8> for InputEventType {
    type Error = CodecError;

    fn try_from(value: u8) -> Result<Self, Self::Error> {
        match value {
            0 => Ok(Self::MouseMove),
            1 => Ok(Self::LeftMouseDown),
            2 => Ok(Self::LeftMouseUp),
            3 => Ok(Self::RightMouseDown),
            4 => Ok(Self::RightMouseUp),
            5 => Ok(Self::ScrollWheel),
            6 => Ok(Self::KeyDown),
            7 => Ok(Self::KeyUp),
            8 => Ok(Self::FlagsChanged),
            9 => Ok(Self::LeftMouseDragged),
            10 => Ok(Self::RightMouseDragged),
            unknown => Err(CodecError::UnknownInputEventType(unknown)),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Modifiers(u16);

impl Modifiers {
    pub const SHIFT: Self = Self(1 << 0);
    pub const CONTROL: Self = Self(1 << 1);
    pub const OPTION: Self = Self(1 << 2);
    pub const COMMAND: Self = Self(1 << 3);
    pub const CAPS_LOCK: Self = Self(1 << 4);

    pub const fn empty() -> Self {
        Self(0)
    }

    pub const fn from_bits_retain(bits: u16) -> Self {
        Self(bits)
    }

    pub const fn bits(self) -> u16 {
        self.0
    }

    pub const fn contains(self, other: Self) -> bool {
        self.0 & other.0 == other.0
    }
}

impl BitOr for Modifiers {
    type Output = Self;

    fn bitor(self, rhs: Self) -> Self::Output {
        Self(self.0 | rhs.0)
    }
}

impl BitOrAssign for Modifiers {
    fn bitor_assign(&mut self, rhs: Self) {
        self.0 |= rhs.0;
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct InputEvent {
    pub event_type: InputEventType,
    pub x: f32,
    pub y: f32,
    pub key_code: u16,
    pub modifiers: Modifiers,
    pub scroll_dx: f32,
    pub scroll_dy: f32,
}

impl InputEvent {
    pub const SIZE: usize = 21;
}

impl WireCodec for InputEvent {
    fn encode(&self) -> Result<Vec<u8>, CodecError> {
        let mut output = Vec::with_capacity(Self::SIZE);
        output.push(self.event_type as u8);
        push_f32(&mut output, self.x);
        push_f32(&mut output, self.y);
        push_u16(&mut output, self.key_code);
        push_u16(&mut output, self.modifiers.bits());
        push_f32(&mut output, self.scroll_dx);
        push_f32(&mut output, self.scroll_dy);
        Ok(output)
    }

    fn decode(input: &[u8]) -> Result<Self, CodecError> {
        let mut decoder = Decoder::new(input);
        let event_type = InputEventType::try_from(decoder.u8("input event type")?)?;
        let x = decoder.f32("input x")?;
        let y = decoder.f32("input y")?;
        let key_code = decoder.u16("input key code")?;
        let modifiers = Modifiers::from_bits_retain(decoder.u16("input modifiers")?);
        let scroll_dx = decoder.f32("input scroll dx")?;
        let scroll_dy = decoder.f32("input scroll dy")?;
        decoder.finish("input event")?;
        Ok(Self {
            event_type,
            x,
            y,
            key_code,
            modifiers,
            scroll_dx,
            scroll_dy,
        })
    }
}

/// Normalizes bottom-left-origin client coordinates for the host wire format.
pub fn normalize_client_coordinates(
    local_x: f32,
    local_y: f32,
    view_width: f32,
    view_height: f32,
) -> (f32, f32) {
    let x = (local_x / view_width).clamp(0.0, 1.0);
    let y = 1.0 - (local_y / view_height).clamp(0.0, 1.0);
    (x, y)
}

/// Maps normalized wire coordinates into host logical pixels.
pub fn map_to_host_pixels(
    normalized_x: f32,
    normalized_y: f32,
    host_width: f32,
    host_height: f32,
) -> (f32, f32) {
    (normalized_x * host_width, normalized_y * host_height)
}

use std::collections::{BTreeMap, HashMap};

use erd_proto::AudioFragment;

const MAX_PENDING_AUDIO_FRAMES: usize = 64;

#[derive(Debug)]
struct PendingAudioFrame {
    fragment_count: u16,
    fragments: BTreeMap<u16, Vec<u8>>,
}

/// Reassembles audio fragments and discards incomplete older frames once newer audio arrives.
#[derive(Debug, Default)]
pub struct AudioFragmentReassembler {
    pending: HashMap<u32, PendingAudioFrame>,
    newest_frame_id: Option<u32>,
    skipped_frames: u64,
}

impl AudioFragmentReassembler {
    pub fn push(&mut self, fragment: AudioFragment) -> Option<Vec<u8>> {
        let frame_id = fragment.header.frame_id;
        if self.newest_frame_id.is_some_and(|newest| frame_id < newest) {
            return None;
        }

        if self.newest_frame_id.is_none_or(|newest| frame_id > newest) {
            self.skip_incomplete_before(frame_id);
            self.newest_frame_id = Some(frame_id);
        }

        if fragment.header.fragment_count == 1 {
            self.pending.remove(&frame_id);
            return Some(fragment.data);
        }

        let entry = self
            .pending
            .entry(frame_id)
            .or_insert_with(|| PendingAudioFrame {
                fragment_count: fragment.header.fragment_count,
                fragments: BTreeMap::new(),
            });
        if entry.fragment_count != fragment.header.fragment_count {
            self.pending.remove(&frame_id);
            self.skipped_frames += 1;
            return None;
        }
        entry
            .fragments
            .entry(fragment.header.fragment_index)
            .or_insert(fragment.data);

        if entry.fragments.len() == entry.fragment_count as usize {
            let entry = self.pending.remove(&frame_id)?;
            let total_bytes = entry.fragments.values().map(Vec::len).sum();
            let mut assembled = Vec::with_capacity(total_bytes);
            for index in 0..entry.fragment_count {
                assembled.extend_from_slice(entry.fragments.get(&index)?);
            }
            return Some(assembled);
        }

        if self.pending.len() > MAX_PENDING_AUDIO_FRAMES {
            let oldest = self.pending.keys().copied().min()?;
            self.pending.remove(&oldest);
            self.skipped_frames += 1;
        }
        None
    }

    pub fn pending_frames(&self) -> usize {
        self.pending.len()
    }

    pub fn skipped_frames(&self) -> u64 {
        self.skipped_frames
    }

    pub fn clear(&mut self) {
        self.pending.clear();
        self.newest_frame_id = None;
    }

    fn skip_incomplete_before(&mut self, frame_id: u32) {
        let before = self.pending.len();
        self.pending.retain(|id, _| *id >= frame_id);
        self.skipped_frames += (before - self.pending.len()) as u64;
    }
}

use std::time::{Duration, Instant};

const LOSS_THRESHOLD: f64 = 0.05;
const REDUCTION_FACTOR: f64 = 0.75;
const STABLE_RECOVERY_AFTER: Duration = Duration::from_secs(30);

/// Adaptive bitrate controller matching the client protocol contract.
#[derive(Debug, Clone)]
pub struct AbrController {
    initial_bitrate: i32,
    current_bitrate: i32,
    min_bitrate: i32,
    max_bitrate: i32,
    stable_since: Option<Instant>,
}

impl AbrController {
    pub fn new(initial_bitrate: i32, min_bitrate: i32, max_bitrate: i32) -> Self {
        assert!(min_bitrate > 0);
        assert!(min_bitrate <= initial_bitrate && initial_bitrate <= max_bitrate);
        Self {
            initial_bitrate,
            current_bitrate: initial_bitrate,
            min_bitrate,
            max_bitrate,
            stable_since: None,
        }
    }

    pub fn current_bitrate(&self) -> i32 {
        self.current_bitrate
    }

    /// Returns a new target bitrate when a control update must be emitted.
    pub fn evaluate(&mut self, loss_ratio: f64, now: Instant) -> Option<i32> {
        if loss_ratio > LOSS_THRESHOLD {
            self.stable_since = None;
            let reduced = ((self.current_bitrate as f64) * REDUCTION_FACTOR) as i32;
            return self.update(reduced.max(self.min_bitrate));
        }

        if loss_ratio <= LOSS_THRESHOLD {
            let stable_since = self.stable_since.get_or_insert(now);
            if now.saturating_duration_since(*stable_since) >= STABLE_RECOVERY_AFTER {
                *stable_since = now;
                let recovered = if self.current_bitrate < self.initial_bitrate {
                    self.initial_bitrate
                } else {
                    ((self.current_bitrate as f64) / REDUCTION_FACTOR) as i32
                };
                return self.update(recovered.min(self.max_bitrate));
            }
        }
        None
    }

    fn update(&mut self, target: i32) -> Option<i32> {
        if target == self.current_bitrate {
            return None;
        }
        self.current_bitrate = target;
        Some(target)
    }
}

use std::{
    fs, io,
    path::{Path, PathBuf},
};

use erd_proto::PAIRING_KEY_SIZE;
use serde::{Deserialize, Serialize};
use thiserror::Error;

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct PairingRecord {
    pub id: String,
    pub name: String,
    pub key: Vec<u8>,
    #[serde(default)]
    pub added_at_unix_ms: u64,
}

impl PairingRecord {
    pub fn key_array(&self) -> Result<[u8; PAIRING_KEY_SIZE], PairingStoreError> {
        self.key
            .as_slice()
            .try_into()
            .map_err(|_| PairingStoreError::InvalidKeyLength(self.key.len()))
    }
}

#[derive(Debug, Clone)]
pub struct PairingStore {
    path: PathBuf,
}

#[derive(Debug, Error)]
pub enum PairingStoreError {
    #[error("pairing store I/O failed: {0}")]
    Io(#[from] io::Error),
    #[error("pairing store JSON failed: {0}")]
    Json(#[from] serde_json::Error),
    #[error("pairing key has length {0}, expected 32")]
    InvalidKeyLength(usize),
    #[error("could not determine the user application data directory")]
    NoApplicationDataDirectory,
}

impl PairingStore {
    pub fn new(path: impl Into<PathBuf>) -> Self {
        Self { path: path.into() }
    }

    pub fn default_path() -> Result<PathBuf, PairingStoreError> {
        #[cfg(target_os = "macos")]
        {
            let home = std::env::var_os("HOME")
                .map(PathBuf::from)
                .ok_or(PairingStoreError::NoApplicationDataDirectory)?;
            return Ok(home
                .join("Library")
                .join("Application Support")
                .join("EclipticRD")
                .join("pairing-keys.json"));
        }
        #[cfg(target_os = "windows")]
        {
            let app_data = std::env::var_os("APPDATA")
                .map(PathBuf::from)
                .ok_or(PairingStoreError::NoApplicationDataDirectory)?;
            return Ok(app_data.join("EclipticRD").join("pairing-keys.json"));
        }
        #[cfg(all(unix, not(target_os = "macos")))]
        {
            let base = std::env::var_os("XDG_DATA_HOME")
                .map(PathBuf::from)
                .or_else(|| {
                    std::env::var_os("HOME").map(|home| PathBuf::from(home).join(".local/share"))
                })
                .ok_or(PairingStoreError::NoApplicationDataDirectory)?;
            return Ok(base.join("EclipticRD").join("pairing-keys.json"));
        }
    }

    pub fn open_default() -> Result<Self, PairingStoreError> {
        Ok(Self::new(Self::default_path()?))
    }

    pub fn path(&self) -> &Path {
        &self.path
    }

    pub fn load_all(&self) -> Result<Vec<PairingRecord>, PairingStoreError> {
        match fs::read(&self.path) {
            Ok(bytes) => {
                let records: Vec<PairingRecord> = serde_json::from_slice(&bytes)?;
                for record in &records {
                    record.key_array()?;
                }
                Ok(records)
            }
            Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(Vec::new()),
            Err(error) => Err(error.into()),
        }
    }

    pub fn load(&self, id: &str) -> Result<Option<PairingRecord>, PairingStoreError> {
        Ok(self.load_all()?.into_iter().find(|record| record.id == id))
    }

    pub fn save(&self, record: PairingRecord) -> Result<(), PairingStoreError> {
        record.key_array()?;
        let mut records = self.load_all()?;
        records.retain(|existing| existing.id != record.id);
        records.push(record);
        self.write_records(&records)
    }

    pub fn delete(&self, id: &str) -> Result<(), PairingStoreError> {
        let mut records = self.load_all()?;
        records.retain(|record| record.id != id);
        self.write_records(&records)
    }

    fn write_records(&self, records: &[PairingRecord]) -> Result<(), PairingStoreError> {
        let parent = self.path.parent().ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "pairing store path has no parent",
            )
        })?;
        fs::create_dir_all(parent)?;
        let temporary = self.path.with_extension("json.tmp");
        let bytes = serde_json::to_vec(records)?;
        write_private(&temporary, &bytes)?;
        fs::rename(&temporary, &self.path)?;
        set_private_permissions(&self.path)?;
        Ok(())
    }
}

fn write_private(path: &Path, bytes: &[u8]) -> io::Result<()> {
    #[cfg(unix)]
    {
        use std::io::Write;
        use std::os::unix::fs::OpenOptionsExt;
        let mut file = fs::OpenOptions::new()
            .write(true)
            .create(true)
            .truncate(true)
            .mode(0o600)
            .open(path)?;
        file.write_all(bytes)?;
        file.sync_all()?;
        return Ok(());
    }
    #[cfg(not(unix))]
    {
        fs::write(path, bytes)
    }
}

fn set_private_permissions(path: &Path) -> io::Result<()> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(path, fs::Permissions::from_mode(0o600))
    }
    #[cfg(not(unix))]
    {
        let _ = path;
        Ok(())
    }
}

