                            .as_millis() as u32;
                        if now_ms >= frame.timestamp_ms && frame.timestamp_ms > 0 {
                            let latency_ms = (now_ms - frame.timestamp_ms) as f64;
                            if latency_ms < 5000.0 {
                                if let Ok(mut lat) = latency_tracker.lock() {
                                    lat.record(latency_ms);
                                }
                            }
                        }
                    }
                    Ok(SessionEvent::Audio(_audio)) => {
                        audio_rx.fetch_add(1, Ordering::Relaxed);
                    }
                    Ok(SessionEvent::Cursor(_cursor)) => {}
                    Ok(SessionEvent::Ping)
                    | Ok(SessionEvent::Clipboard(_))
                    | Ok(SessionEvent::Ignored) => {}
                    Err(erd_app::SessionError::Io(e))
                        if e.kind() == std::io::ErrorKind::TimedOut
                            || e.kind() == std::io::ErrorKind::WouldBlock =>
                    {
                        // regular slice timeout
                    }
                    Err(erd_app::SessionError::NotReady) => {
                        break;
                    }
                    Err(e) => {
                        tracing::debug!("UDP pipeline event error: {e}");
                        std::thread::sleep(Duration::from_millis(10));
                    }
                }
            }
        });

        if let Ok(mut sess_lock) = state.session.lock() {
            *sess_lock = Some(session);
        }
        if let Ok(mut tcp_lock) = state.tcp_runtime.lock() {
            *tcp_lock = Some(tcp_runtime);
        }
        if let Ok(mut udp_lock) = state.udp_handle.lock() {
            *udp_lock = Some(udp_task);
        }

        Ok(ConnectResponse {
            pairing_id: ready_session.pairing.id,
            host_name: ready_session.pairing.name,
            server_name: ready_session.server.name,
        })
    }

    #[tauri::command]
    pub async fn disconnect(state: State<'_, AppState>) -> Result<(), String> {
        disconnect_internal(&state).await
    }

    #[tauri::command]
    pub fn stats(state: State<'_, AppState>) -> Result<SessionStats, String> {
        let connected = state
            .session
            .lock()
            .map_err(|e| e.to_string())?
            .as_ref()
            .map(|s| {
                s.state().unwrap_or(erd_app::SessionState::Disconnected)
                    == erd_app::SessionState::Ready
            })
            .unwrap_or(false);

        let (latency_p50_ms, latency_p99_ms) = state
            .latency
            .lock()
            .map(|lat| lat.percentiles())
            .unwrap_or((None, None));

        Ok(SessionStats {
            connected,
            frames_received: state.frames_received.load(Ordering::Relaxed),
            frames_decoded: state.frames_decoded.load(Ordering::Relaxed),
            audio_packets_received: state.audio_packets_received.load(Ordering::Relaxed),
            latency_p50_ms,
            latency_p99_ms,
        })
    }

    #[tauri::command]
    pub fn send_input(state: State<'_, AppState>, event: InputPayload) -> Result<(), String> {
        let sess_opt = state.session.lock().map_err(|e| e.to_string())?.clone();
        let session = sess_opt.ok_or_else(|| "Session not initialized".to_string())?;

        let event_type = match event.event_type.as_str() {
            "MouseMove" => InputEventType::MouseMove,
            "LeftMouseDown" => InputEventType::LeftMouseDown,
            "LeftMouseUp" => InputEventType::LeftMouseUp,
            "RightMouseDown" => InputEventType::RightMouseDown,
            "RightMouseUp" => InputEventType::RightMouseUp,
            "ScrollWheel" => InputEventType::ScrollWheel,
            "KeyDown" => InputEventType::KeyDown,
            "KeyUp" => InputEventType::KeyUp,
            "FlagsChanged" => InputEventType::FlagsChanged,
            "LeftMouseDragged" => InputEventType::LeftMouseDragged,
            "RightMouseDragged" => InputEventType::RightMouseDragged,
            other => return Err(format!("Unknown event type: {other}")),
        };

        let modifiers = Modifiers::from_bits_retain(event.modifiers);

        let input_event = match event_type {
            InputEventType::KeyDown | InputEventType::KeyUp => {
                let key_code = event.key_code.unwrap_or(0);
                key_event(event_type, InputKey::WindowsVirtualKey(key_code), modifiers)
                    .ok_or_else(|| format!("Unsupported key code: {key_code}"))?
            }
            _ => {
                let vw = if event.view_width > 0.0 {
                    event.view_width
                } else {
                    1280.0
                };
                let vh = if event.view_height > 0.0 {
                    event.view_height
                } else {
                    800.0
                };
                pointer_event(
                    event_type,
                    event.x,
                    event.y,
                    vw,
                    vh,
                    modifiers,
                    event.scroll_dx,
                    event.scroll_dy,
                )
                .ok_or_else(|| "Invalid pointer coordinates".to_string())?
            }
        };

        session
            .send_input(input_event)
            .map_err(|e| format!("Failed to send input: {e}"))
    }
}

async fn disconnect_internal(state: &AppState) -> Result<(), String> {
    state.stop_udp_flag.store(true, Ordering::SeqCst);

    if let Ok(mut tcp_lock) = state.tcp_runtime.lock() {
        if let Some(mut tcp) = tcp_lock.take() {
            tcp.stop();
        }
    }

    let udp_task = {
        if let Ok(mut udp_lock) = state.udp_handle.lock() {
            udp_lock.take()
        } else {
            None
        }
    };
    if let Some(handle) = udp_task {
        handle.abort();
    }

    if let Ok(mut sess_lock) = state.session.lock() {
        if let Some(sess) = sess_lock.take() {
            let _ = sess.disconnect();
        }
    }

    Ok(())
}

